'use strict';
function leaveShip(){inLobby=true;document.getElementById('lobby').hidden=false;}
function devAction(action){switch(action){case 'give':{const type=el('devitem').value,n=clamp(Math.floor(+el('devamount').value)||1,1,512);if(el('devtarget').value==='outside')addWorldLoot(type,ship.getWorldPoint(V(bounds.r+4,0)),n);else giveItem(type,n);break;}case 'seed':{const seed=Number(el('devseed').value);if(!Number.isSafeInteger(seed)||seed<0||seed>=1e6)return toast('Enter a seed from 0 to 999999.');if(!isCombatZone())return toast('Travel to a combat zone first.');snapshotZone();zoneData[zone]={seed,mined:[],loot:zoneData[zone]?.loot||[]};setupZone(true);break;}case 'heal':shipHP=shipMaxHP();break;case 'damage':damageShip(shipMaxHP()*.25);break;case 'tiles':for(const t of [...blocks.values(),...terrain.values()])t.hp=100;break;case 'damagetile':{const p=localPlayer(),tile=[...blocks.values(),...terrain.values()].sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(tile)tile.hp=25;break;}case 'spawnbot':{const sp=el('devbot').value,list=zoneData[zone]?.bots?.[sp];const i=list?list.findIndex(r=>r?.dead):-1;if(i<0)return toast('No dead '+sp+' bot to respawn in this zone.');if(spawnBot(sp,null,i))list[i]={dead:false};break;}case 'killbots':for(const b of botsOf(el('devbot').value))damageBot(1e9,b.species,b.index);break;case 'ai':botsPaused=!botsPaused;el('dev-ai').textContent=botsPaused?'Resume bot AI':'Pause bot AI';break;case 'shots':shots=[];enemyShots=[];break;case 'wake':for(const i of [...items,...boxes,...worldLoot])wakeCargo(i.body);break;case 'sleep':for(const i of [...items,...boxes,...worldLoot])if(!cargoWakeLocks.get(i.body)?.size&&i.body.getLinearVelocity().length()<.1)i.body.setAwake(false);break;case 'recover':recover();break;case 'mission':startMission(el('devmission').value);break;case 'endmission':if(!missionState.active)return toast('No mission is running.');endMission();break;case 'treasure':if(!missionState.active)return toast('Start a mission first.');missionState.elapsed+=MISSIONS.treasureEverySeconds;missionState.endsIn=Math.max(30,missionState.endsIn-MISSIONS.treasureEverySeconds);refreshTreasure();break;default:if(ZONES[action]){snapshotZone();zone=action;setupZone(true);}}save(true);el('devstatus').textContent=zone+' · '+items.length+' interior stacks · '+worldLoot.length+' exterior crates · '+cargoSleepStats()+' · shields '+Math.ceil(shipHP)+' / '+shipMaxHP();}
// Main menu: multiplayer only. Enter the server address (filled in automatically when the page comes from a
// notdred.io server), your name and, optionally, the host's token; every ship on the server shows as a card.
const lobbyMarkup=`<section id="lobby"><nav>notdred.io <small>[FAN PROTOTYPE · ${BUILD.label} ${BUILD.date}]</small> <span>${Object.values(ZONES).map(z=>z.name).join(' · ')}</span></nav><aside><fieldset><legend>Server</legend><label>Address<input id="serverurl" aria-label="Server address" placeholder="wss://your-server/play" autocomplete="off"></label><label>Token<input id="devtoken" type="password" aria-label="Server token" placeholder="Host token (optional)" autocomplete="off"></label><button id="connectserver" class="primary">Connect</button><p id="networkstatus">Not connected.</p></fieldset><fieldset><legend>Account</legend><label>Name<input id="crewname" value="Player" maxlength="24"></label><small>Leaving a ship drops your carried inventory aboard it. A ship left empty for a minute is returned to its Freeport.</small><p><label class="litetoggle"><input type="checkbox" id="litemode"> Reduced mode (slow computers)</label></p><small><a href="/classic">Classic mode</a> for very old browsers</small></fieldset><fieldset><legend>Ship List</legend><label>Search: <input id="shipsearch" placeholder="Ship name"></label><p><button id="refreshrooms">Refresh ↻</button> <button id="ownedonly" aria-pressed="false">Owned</button></p><button id="importship">Import ship…</button></fieldset></aside><main><div class="realm"><h1 id="realmname">Not connected</h1><p id="realmnote">Enter a server address and press Connect.</p></div><h2>Click a ship to join!</h2><div class="shipcards" id="shipcards"></div><p>WASD move · E helm · Q throw · R rotate / pusher mode · Enter chat · / leaderboard</p><a href="source.zip">Download source + README</a></main></section>`;
if(typeof Image!=='undefined'){
 document.body.insertAdjacentHTML('beforeend',lobbyMarkup);inLobby=true;
 const leave=document.createElement('button');leave.textContent='Leave ship';leave.onclick=leaveShip;el('save').parentElement.appendChild(leave);
 el('dev').innerHTML=`<h2>Developer controls</h2><fieldset><legend>Items & resources</legend><select id="devitem" aria-label="Item">${TYPES.map(t=>`<option value="${t}">${NAMES[t]}</option>`).join('')}</select><input id="devamount" aria-label="Quantity" type="number" min="1" max="512" value="16"><select id="devtarget" aria-label="Spawn location"><option value="inside">Inventory / floor overflow</option><option value="outside">Exterior crate</option></select><button data-dev="give">Give item</button></fieldset><fieldset><legend>Zones · ${BUILD.label} build</legend>${Object.values(ZONES).map(z=>`<button data-dev="${z.id}">${z.name}</button>`).join('')}<br><input id="devseed" aria-label="Seed" type="number" min="0" max="999999" value="0"><button data-dev="seed">Regenerate current zone with seed</button></fieldset><fieldset><legend>Missions (ℵ33)</legend><select id="devmission" aria-label="Mission zone">${MISSIONS.rotation.map(id=>`<option value="${id}">${ZONES[id].name}</option>`).join('')}</select><button data-dev="mission">Spawn mission now</button><button data-dev="endmission">End current mission</button><button data-dev="treasure">Advance mission 5 min (new treasure)</button></fieldset><fieldset><legend>Damage & repair</legend><button data-dev="damage">Damage shields 25%</button><button data-dev="heal">Restore shields</button><button data-dev="damagetile">Damage nearest tile</button><button data-dev="tiles">Repair all tiles</button><button data-dev="recover">Unstick player</button></fieldset><fieldset><legend>Bots & weapons</legend><select id="devbot" aria-label="Bot species">${Object.entries(BOT_TYPES).map(([k,b])=>`<option value="${k}">${b.label}</option>`).join('')}</select><button data-dev="spawnbot">Respawn one now</button><button data-dev="killbots">Kill all of species (drops loot)</button><button id="dev-ai" data-dev="ai">Pause bot AI</button><button data-dev="shots">Clear projectiles</button></fieldset><fieldset><legend>Physics</legend><button data-dev="wake">Wake cargo</button><button data-dev="sleep">Sleep idle cargo</button></fieldset><p id="devstatus"></p><button id="closedev">Close</button>`;
 el('dev').querySelectorAll('[data-dev]').forEach(b=>b.onclick=()=>devAction(b.dataset.dev));el('closedev').onclick=()=>el('dev').close();
 // Shared renderer: wedge silhouettes use the supplied block/walkway textures in
 // every context, including inventory. The input images remain unmodified.
 Promise.all(Object.values(spriteImages).map(im=>im.complete?Promise.resolve():new Promise(resolve=>{im.onload=resolve;im.onerror=resolve;}))).then(()=>{
  for(const type of ['fabricator','storage','thruster','starter','ejector']){const c=document.createElement('canvas');c.width=c.height=96;const g=c.getContext('2d');g.imageSmoothingEnabled=false;const put=(name,x,y,w,h)=>{const im=spriteImages[name];if(im?.naturalWidth)g.drawImage(im,x,y,w,h);};if(type==='fabricator'){put('official-fabricator',16,0,64,96);put('official-fab_t_legacy',55,3,20,25);put('official-fab_screen',55,32,20,25);put('official-fab_hatch',22,63,20,13);put('official-fab_hatch',22,77,20,13);}else if(type==='storage'){put('official-exbox_base',0,0,96,96);put('official-exbox_center',12,12,72,72);}else if(type==='ejector')put('official-item_ejector',8,0,80,96);else if(type==='turret'||type==='starter_rc'){put('official-turret_base',0,18,20,60);put('official-turret_barrel_rc'+(type==='starter_rc'?'_starter':''),12,40,84,16);put('official-turret_action_rc'+(type==='starter_rc'?'_starter':''),16,36,24,24);}else {const im=spriteImages[type==='starter'?'official-thruster_starter':'official-thruster'];if(im?.naturalWidth)g.drawImage(im,0,38,40,82,25,0,46,94);}const im=new Image();im.src=c.toDataURL();im.renderURL=im.src;spriteImages[type]=im;}
  // Burst/auto turret and turret-controller item icons, drawn from the game's own turret parts, used only when the
  // original item icons (scripts/fetch-item-icons.sh) are not present.
  const turretIcons=()=>{for(const type of ['turret_burst','turret_auto','turret_controller']){const cur=spriteImages[type];if(cur?.naturalWidth&&!cur.composite)continue;if(cur&&!cur.failed&&!cur.complete)continue;const c=document.createElement('canvas');c.width=c.height=96;const g=c.getContext('2d');g.imageSmoothingEnabled=false;const put=(name,x,y,w,h)=>{const im=spriteImages[name];if(im?.naturalWidth)g.drawImage(im,x,y,w,h);};
   if(type==='turret_controller')put('official-turret_controller',32,0,32,96);else{put('official-turret_base',0,18,20,60);put(type==='turret_burst'?'official-turret_barrel_burst':'official-turret_barrel',12,40,84,16);put(type==='turret_burst'?'official-turret_action_burst':'official-turret_action_auto',16,36,24,24);}
   const im=new Image();im.src=c.toDataURL();im.renderURL=im.src;im.composite=true;spriteImages[type]=im;}};turretIcons();setTimeout(turretIcons,1500);
  for(const type of ['wedge','walkway_wedge']){const c=document.createElement('canvas');c.width=c.height=80;const g=c.getContext('2d');g.beginPath();g.moveTo(0,0);g.lineTo(80,80);g.lineTo(0,80);g.closePath();g.clip();g.drawImage(spriteImages[type==='wedge'?'block':'walkway'],0,0,80,80);g.strokeStyle='#151515';g.lineWidth=5;g.beginPath();g.moveTo(0,0);g.lineTo(80,80);g.stroke();const im=new Image();im.src=c.toDataURL();im.renderURL=im.src;spriteImages[type]=im;}
 });
}
